# Tiny SVG toolkit for Revise Shorts diagrams (all original, generated by script).
import math
INK='#1d1d1f'; BL='#2b8fd0'; OR='#e8792b'; PU='#9a5bd3'; GR='#4aa516'; RD='#d9363e'; GY='#8a8f98'; LT='#eef2f6'
FONT="system-ui,-apple-system,'Segoe UI',Roboto,sans-serif"
def f(x): return f'{x:.1f}'.rstrip('0').rstrip('.')
def esc(s): return str(s).replace('&','&amp;').replace('<','&lt;').replace('>','&gt;')
def svg(w,h,body,alt):
    return (f'<svg viewBox="0 0 {w} {h}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="{esc(alt)}" '
            f'font-family="{FONT}" font-size="13" fill="none" stroke-linecap="round" stroke-linejoin="round">'
            f'<rect x="0" y="0" width="{w}" height="{h}" rx="10" fill="#fff" stroke="none"/>{"".join(body)}</svg>')
def L(x1,y1,x2,y2,c=INK,w=2,dash=None):
    d=f' stroke-dasharray="{dash}"' if dash else ''
    return f'<line x1="{f(x1)}" y1="{f(y1)}" x2="{f(x2)}" y2="{f(y2)}" stroke="{c}" stroke-width="{w}"{d}/>'
def PL(pts,c=INK,w=2,dash=None,fill='none',close=False):
    d=f' stroke-dasharray="{dash}"' if dash else ''
    tag='polygon' if close else 'polyline'
    return f'<{tag} points="{" ".join(f(x)+","+f(y) for x,y in pts)}" stroke="{c}" stroke-width="{w}" fill="{fill}"{d}/>'
def P(d,c=INK,w=2,fill='none',dash=None,op=None):
    a=f' stroke-dasharray="{dash}"' if dash else ''
    if op is not None: a+=f' fill-opacity="{op}"'
    return f'<path d="{d}" stroke="{c}" stroke-width="{w}" fill="{fill}"{a}/>'
def C(x,y,r,c=INK,w=2,fill='none',dash=None):
    d=f' stroke-dasharray="{dash}"' if dash else ''
    return f'<circle cx="{f(x)}" cy="{f(y)}" r="{f(r)}" stroke="{c}" stroke-width="{w}" fill="{fill}"{d}/>'
def R(x,y,w,h,c=INK,sw=2,fill='none',rx=0,op=None,dash=None):
    a=f' fill-opacity="{op}"' if op is not None else ''
    if dash: a+=f' stroke-dasharray="{dash}"'
    return f'<rect x="{f(x)}" y="{f(y)}" width="{f(w)}" height="{f(h)}" rx="{rx}" stroke="{c}" stroke-width="{sw}" fill="{fill}"{a}/>'
def T(x,y,s,c=INK,size=13,a='middle',b=False,i=False,rot=None):
    st=(' font-weight="700"' if b else '')+(' font-style="italic"' if i else '')
    tr=f' transform="rotate({rot} {f(x)} {f(y)})"' if rot is not None else ''
    import re
    parts=re.split(r'_(\{[^}]*\}|[A-Za-z0-9]+)',str(s)); body=esc(parts[0])
    for k in range(1,len(parts),2):
        body+=f'<tspan dy="{size*0.3:.1f}" font-size="{size*0.72:.1f}">{esc(parts[k].strip("{}"))}</tspan>'
        if parts[k+1]: body+=f'<tspan dy="{-size*0.3:.1f}">{esc(parts[k+1])}</tspan>'
    return f'<text x="{f(x)}" y="{f(y)}" fill="{c}" stroke="none" font-size="{size}" text-anchor="{a}" dominant-baseline="middle"{st}{tr}>{body}</text>'
def head(x,y,ang,c=INK,s=9):
    a1,a2=ang+math.radians(155),ang-math.radians(155)
    return PL([(x,y),(x+s*math.cos(a1),y+s*math.sin(a1)),(x+s*math.cos(a2),y+s*math.sin(a2))],c,1,fill=c,close=True)
def A(x1,y1,x2,y2,c=INK,w=2,s=9,both=False,dash=None):
    ang=math.atan2(y2-y1,x2-x1); bx,by=x2-0.6*s*math.cos(ang),y2-0.6*s*math.sin(ang)
    out=[L(x1 if not both else x1+0.6*s*math.cos(ang),y1 if not both else y1+0.6*s*math.sin(ang),bx,by,c,w,dash),head(x2,y2,ang,c,s)]
    if both: out.append(head(x1,y1,ang+math.pi,c,s))
    return ''.join(out)
def curly(x1,y1,cx,cy,x2,y2,c=RD,w=1.8,half=False):
    "quadratic curly arrow (mechanisms); half=True gives a fish-hook"
    ang=math.atan2(y2-cy,x2-cx)
    return P(f'M{f(x1)},{f(y1)} Q{f(cx)},{f(cy)} {f(x2-5*math.cos(ang))},{f(y2-5*math.sin(ang))}',c,w)+head(x2,y2,ang,c,8)
def G(body,tx=0,ty=0,sc=1): return f'<g transform="translate({f(tx)} {f(ty)}) scale({sc})">{"".join(body)}</g>'
class Ax:
    "plotting frame: pixel box (x,y,w,h) with data ranges"
    def __init__(s,x,y,w,h,x0,x1,y0,y1): s.x,s.y,s.w,s.h,s.x0,s.x1,s.y0,s.y1=x,y,w,h,x0,x1,y0,y1
    def X(s,v): return s.x+(v-s.x0)/(s.x1-s.x0)*s.w
    def Y(s,v): return s.y+s.h-(v-s.y0)/(s.y1-s.y0)*s.h
    def axes(s,xl='',yl='',ox=None,oy=None,ticks=False):
        ox=s.x0 if ox is None else ox; oy=s.y0 if oy is None else oy
        X0,Y0=s.X(ox),s.Y(oy); out=[A(s.x-4 if ox==s.x0 else s.x,Y0,s.x+s.w+8,Y0,INK,1.6,7),A(X0,s.y+s.h+4 if oy==s.y0 else s.y+s.h,X0,s.y-8,INK,1.6,7)]
        if xl: out.append(T(s.x+s.w+6,Y0+14,xl,size=12,a='end',i=len(xl)<3))
        if yl: out.append(T(X0+6,s.y-6,yl,size=12,a='start',i=len(yl)<3))
        return ''.join(out)
    def curve(s,fn,a,b,c=BL,w=2.4,n=160,dash=None): return s.segs(fn,a,b,c,w,n,dash)
    def segs(s,fn,a,b,c=BL,w=2.4,n=160,dash=None):
        "curve broken where it leaves the y-range"
        out=[];pts=[]
        for k in range(n+1):
            t=a+(b-a)*k/n
            try: v=fn(t)
            except (ValueError,ZeroDivisionError): v=None
            if v is None or not (s.y0<=v<=s.y1):
                if len(pts)>1: out.append(PL(pts,c,w,dash))
                pts=[]; continue
            pts.append((s.X(t),s.Y(v)))
        if len(pts)>1: out.append(PL(pts,c,w,dash))
        return ''.join(out)
    def area(s,fn,a,b,c=BL,op=0.22,n=80,base=0):
        pts=[(s.X(a),s.Y(base))]+[(s.X(a+(b-a)*k/n),s.Y(fn(a+(b-a)*k/n))) for k in range(n+1)]+[(s.X(b),s.Y(base))]
        return f'<polygon points="{" ".join(f(x)+","+f(y) for x,y in pts)}" fill="{c}" fill-opacity="{op}" stroke="none"/>'
    def dot(s,a,b,c=INK,r=3.5): return C(s.X(a),s.Y(b),r,c,1,fill=c)
    def xt(s,v,lab,dy=14,c=INK,size=12): return L(s.X(v),s.Y(s.y0 if s.y0>=0 else 0)-3,s.X(v),s.Y(s.y0 if s.y0>=0 else 0)+3,INK,1.4)+T(s.X(v),s.Y(s.y0 if s.y0>=0 else 0)+dy,lab,c,size)
    def yt(s,v,lab,c=INK,size=12): ox=s.X(s.x0 if s.x0>=0 else 0); return L(ox-3,s.Y(v),ox+3,s.Y(v),INK,1.4)+T(ox-6,s.Y(v),lab,c,size,a='end')
# ---- circuit symbols, centred at (x,y); o='h' horizontal wire, 'v' vertical
def _rot(o,body,x,y): return f'<g transform="translate({f(x)} {f(y)})'+(' rotate(90)' if o=='v' else '')+f'">{body}</g>'
def resistor(x,y,o='h',lab=None,c=INK):
    b=R(-16,-7,32,14,c,2,fill='#fff'); out=_rot(o,b,x,y)
    if lab: out+=T(x,y-17,lab,size=12) if o=='h' else T(x+20,y,lab,size=12,a='start')
    return out
def cell(x,y,o='h',lab=None,n=1):
    b=R(-6*n-2,-16,12*n+4,32,'#fff',0,fill='#fff')
    for k in range(n):
        dx=-6*(n-1)+12*k
        b+=L(dx-3,-14,dx-3,14,INK,2)+L(dx+3,-7,dx+3,7,INK,4)
    out=_rot(o,b,x,y)
    if lab: out+=T(x,y-24,lab,size=12) if o=='h' else T(x+22,y,lab,size=12,a='start')
    return out
def meter(x,y,letter,o='h'): return C(x,y,12,INK,2,fill='#fff')+T(x,y+1,letter,size=13,b=True)
def bulb(x,y,o='h'):
    return C(x,y,11,INK,2,fill='#fff')+L(x-7.8,y-7.8,x+7.8,y+7.8,INK,1.6)+L(x-7.8,y+7.8,x+7.8,y-7.8,INK,1.6)
def capacitor(x,y,o='h',lab=None):
    b=R(-5,-14,10,28,'#fff',0,fill='#fff')+L(-4,-13,-4,13,INK,2.6)+L(4,-13,4,13,INK,2.6)
    out=_rot(o,b,x,y)
    if lab: out+=T(x,y-21,lab,size=12) if o=='h' else T(x+20,y,lab,size=12,a='start')
    return out
def switch(x,y,o='h'):
    b=R(-14,-10,28,12,'#fff',0,fill='#fff')+C(-12,0,2.4,INK,1.5,fill='#fff')+C(12,0,2.4,INK,1.5,fill='#fff')+L(-10,-1,11,-11,INK,2)
    return _rot(o,b,x,y)
def ldr(x,y,o='h',lab=None):
    b=C(0,0,19,INK,1.6,fill='#fff')+R(-12,-5,24,10,INK,2,fill='#fff')+A(-20,-26,-9,-14,INK,1.4,6)+A(-11,-29,0,-17,INK,1.4,6)
    out=_rot(o,b,x,y)
    if lab: out+=T(x+26,y,lab,size=12,a='start') if o=='v' else T(x,y+30,lab,size=12)
    return out
def thermistor(x,y,o='h',lab=None):
    b=R(-14,-6,28,12,INK,2,fill='#fff')+PL([(-14,12),(-8,12),(12,-12)],INK,1.5)
    out=_rot(o,b,x,y)
    if lab: out+=T(x+22,y,lab,size=12,a='start') if o=='v' else T(x,y+24,lab,size=12)
    return out
def diode(x,y,o='h'):
    b=R(-10,-10,20,20,'#fff',0,fill='#fff')+PL([(-8,-9),(-8,9),(7,0)],INK,2,fill='#fff',close=True)+L(8,-9,8,9,INK,2.4)
    return _rot(o,b,x,y)
def wire(pts,c=INK): return PL(pts,c,2)
def junc(x,y): return C(x,y,3.2,INK,1,fill=INK)
# ---- chemistry helpers
def atom(x,y,s,c=INK,size=15,bg=True):
    w=max(10,len(s)*8.4)
    return (R(x-w/2-1,y-10,w+2,20,'#fff',0,fill='#fff') if bg else '')+T(x,y+1,s,c,size,b=False)
def bond(x1,y1,x2,y2,n=1,c=INK,w=1.8,gap=3.2):
    if n==1: return L(x1,y1,x2,y2,c,w)
    dx,dy=x2-x1,y2-y1; d=math.hypot(dx,dy); nx,ny=-dy/d*gap,dx/d*gap
    if n==2: return L(x1+nx,y1+ny,x2+nx,y2+ny,c,w)+L(x1-nx,y1-ny,x2-nx,y2-ny,c,w)
    return L(x1,y1,x2,y2,c,w)+L(x1+2*nx,y1+2*ny,x2+2*nx,y2+2*ny,c,w)+L(x1-2*nx,y1-2*ny,x2-2*nx,y2-2*ny,c,w)
def wedge(x1,y1,x2,y2,c=INK,wd=6):
    dx,dy=x2-x1,y2-y1; d=math.hypot(dx,dy); nx,ny=-dy/d*wd/2,dx/d*wd/2
    return PL([(x1,y1),(x2+nx,y2+ny),(x2-nx,y2-ny)],c,1,fill=c,close=True)
def hashb(x1,y1,x2,y2,c=INK,wd=7,n=6):
    dx,dy=x2-x1,y2-y1; d=math.hypot(dx,dy); nx,ny=-dy/d,dx/d; out=''
    for k in range(1,n+1):
        t=k/n; px,py=x1+dx*t,y1+dy*t; hw=wd/2*t
        out+=L(px-nx*hw,py-ny*hw,px+nx*hw,py+ny*hw,c,1.4)
    return out
def lp(x,y,ang=0,c=INK):
    "lone pair: two dots perpendicular to direction ang (deg)"
    a=math.radians(ang); nx,ny=-math.sin(a)*3.2,math.cos(a)*3.2
    return C(x+nx,y+ny,1.7,c,1,fill=c)+C(x-nx,y-ny,1.7,c,1,fill=c)
